import {routePreview,monthlyPayment} from './engine.mjs';
import {levelOf,incomeAt} from './levels.mjs';
const names={vi:{start:'Khởi đầu',opportunity:'Cơ hội',expense:'Bất ngờ',learn:'Kiến thức',market:'Thị trường',salary:'Thu nhập'},en:{start:'Start',opportunity:'Opportunity',expense:'Unexpected',learn:'Knowledge',market:'Market',salary:'Income'}};
const money=n=>(n<0?'−':'')+'$'+Math.abs(n).toLocaleString('en-US',{maximumFractionDigits:0});
export function routeChoicesHTML(s,lang='vi',attribute='data-action',prefix='route-',disabled=false){const vi=lang==='vi',t=(a,b)=>vi?a:b,l=levelOf(s),month=Math.min(12,s.month+1),cashAtLanding=s.cash+incomeAt(s,month)-l.living-(l.pressure[month]||0)-monthlyPayment(s);return `<div class="route-choice-grid">${s.route.dice.map((_,i)=>{const p=routePreview(s,i);return `<button type="button" class="route-choice" ${attribute}="${prefix+i}" ${disabled?'disabled':''}><strong>${names[lang][p.type]} · ${t('ô','space')} ${p.destination+1}</strong>${p.type==='opportunity'?`<span>${t('Vốn cần','Entry cash')}: <b>${money(p.cost)}</b> · ${p.locked?t('Khóa vốn đến hết chặng','Capital locked to stage end'):t('Có thể bán trong chặng','Can be sold during the stage')}</span><span>${t('Đánh đổi','Trade-off')}: ${p.kind==='crypto'?t('Biến động cao; không có thu nhập cố định','High volatility; no fixed income'):p.kind==='equity'||p.kind==='fund'?t('Biến động thị trường; không có cổ tức trong mô hình','Market exposure; no modeled dividends'):t('Rủi ro kinh doanh/định giá; tiền chia không đảm bảo','Business/valuation risk; distributions are uncertain')}</span>${p.debtAdded?`<span class="route-caution">${t('Tạo thêm nợ','Adds debt')}: ${money(p.debtAdded)} · ${money(p.payment)}/${t('tháng','month')}</span>`:''}<span class="${cashAtLanding<p.cost?'route-caution':''}">${t('Tiền mặt dự tính sau mua','Estimated cash after buying')}: <b>${money(cashAtLanding-p.cost)}</b></span>`:`<span>${t('Tình huống cụ thể vẫn chưa được tiết lộ.','The specific scenario is still hidden.')}</span>`}</button>`;}).join('')}</div>${s.route.dice.some((_,i)=>routePreview(s,i).type==='opportunity')?`<p class="route-disclosure">${t('So sánh vốn và thanh khoản trước khi chọn. Dự tính chỉ dùng thu–chi bắt buộc đã biết, chưa tính biến động danh mục hoặc khoản bất ngờ. Chọn ô chưa phải đồng ý mua; bạn vẫn được bỏ qua sau khi mở thẻ.','Compare capital needs and liquidity before choosing. Estimates use known mandatory cash flows, excluding portfolio changes and surprises. Choosing a space does not commit you to buying; you can still pass after opening the card.')}</p>`:''}`;}
